import{_ as a,o as s,c as o,a2 as t}from"./chunks/framework.C8822HRV.js";const m=JSON.parse('{"title":"Project folders after sdd init","description":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply.","frontmatter":{"title":"Project folders after sdd init","description":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply.","head":[["meta",{"property":"og:title","content":"Project folders after sdd init · sdd"}],["meta",{"property":"og:description","content":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply."}],["meta",{"property":"og:url","content":"https://harsha09.github.io/spec-driven-development/reference/layout/"}],["meta",{"property":"og:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["meta",{"name":"twitter:title","content":"Project folders after sdd init · sdd"}],["meta",{"name":"twitter:description","content":"What folders sdd creates in your app — .sdd, memory, changes, and optional AI host files — explained simply."}],["meta",{"name":"twitter:image","content":"https://harsha09.github.io/spec-driven-development/og.jpg"}],["link",{"rel":"canonical","href":"https://harsha09.github.io/spec-driven-development/reference/layout/"}]]},"headers":[],"relativePath":"reference/layout.md","filePath":"reference/layout.md","lastUpdated":1792757203000}'),n={name:"reference/layout.md"};function d(i,e,r,c,l,p){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="project-folders" tabindex="-1">Project folders <a class="header-anchor" href="#project-folders" aria-label="Permalink to &quot;Project folders&quot;">​</a></h1><p>After <code>sdd init</code>, your app looks roughly like this:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>.sdd/                 ← sdd settings and the short playbook</span></span>
<span class="line"><span>  config.yaml</span></span>
<span class="line"><span>  protocol.md         ← rules for you + the AI</span></span>
<span class="line"><span>  active-context.md   ← what you’re doing right now</span></span>
<span class="line"><span>  handoff.md          ← brief the AI just saw</span></span>
<span class="line"><span>  mcp.yaml            ← external MCP sources sdd calls (optional)</span></span>
<span class="line"><span>  workflows/          ← paths like hotfix, feature, greenfield</span></span>
<span class="line"><span>  templates/</span></span>
<span class="line"><span>memory/               ← longer-lived product notes (keep short)</span></span>
<span class="line"><span>  index.md</span></span>
<span class="line"><span>  constitution.md     ← non-negotiables</span></span>
<span class="line"><span>  …</span></span>
<span class="line"><span>changes/              ← one folder per piece of work</span></span>
<span class="line"><span>  &lt;id&gt;/</span></span>
<span class="line"><span>    meta.yaml         ← stage + status</span></span>
<span class="line"><span>    *.md              ← short notes for this work</span></span>
<span class="line"><span>domains/              ← optional extra docs by area</span></span>
<span class="line"><span>AGENTS.md             ← tiny pointer for AIs</span></span>
<span class="line"><span># only for the AI you picked:</span></span>
<span class="line"><span># .github/agents/  or  .grok/rules/  or  .claude/agents/  or  .ollama/  or  .kilo/</span></span></code></pre></div><h2 id="what-belongs-in-git" tabindex="-1">What belongs in git <a class="header-anchor" href="#what-belongs-in-git" aria-label="Permalink to &quot;What belongs in git&quot;">​</a></h2><p>Commit the shared process: <code>.sdd/config.yaml</code>, <code>.sdd/workflows/</code>, <code>.sdd/templates/</code>, <code>.sdd/protocol.md</code>, <code>memory/</code>, and each change pack under the configured changes directory.</p><p>Ignore per-machine files. Init writes <code>.sdd/.gitignore</code> for <code>handoff.md</code> and <code>active-context.md</code>, and <code>&lt;changes_path&gt;/.gitignore</code> for <code>.active</code> (by default <code>changes/.active</code>). <code>.active</code> is the live change pointer. <code>handoff.md</code> and <code>active-context.md</code> are a repo-relative handoff and task brief. Commands that move or launch work rewrite them; they do not change on every command. If git already tracks one of them, init warns and leaves the index alone. A second non-interactive <code>sdd init</code> without <code>--force</code> appends missing ignore lines, including <code>role-runs/</code>, and does not rewrite config, memory, or workflows. Confirming the re-init prompt in a terminal still behaves like <code>--force</code>. <code>sdd init --force</code> appends any missing ignore lines and refreshes unchanged generated files. A workflow or template with no manifest hash is recorded as generated when its bytes match the bundled file, so a later <code>--force</code> can refresh it. A file that differs stays kept. <code>sdd workflows</code> names bundled workflows that are not in the project yet. <code>.sdd/prices.yaml</code> is committed project config, written by init when missing, and not regenerated over a user edit.</p><h2 id="keep-project-data-together" tabindex="-1">Keep project data together <a class="header-anchor" href="#keep-project-data-together" aria-label="Permalink to &quot;Keep project data together&quot;">​</a></h2><p>Use <code>--root</code> during initialization to place SDD&#39;s project data under one relative directory while keeping <code>.sdd/config.yaml</code>, workflows, and templates at their normal locations:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sdd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> init</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --here</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --root</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .sdd</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --ai</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> copilot</span></span></code></pre></div><p>This sets <code>memory_path</code>, <code>changes_path</code>, <code>domains_path</code>, and <code>archive_path</code> to <code>.sdd/memory</code>, <code>.sdd/changes</code>, <code>.sdd/domains</code>, and <code>.sdd/archive</code> before those folders are created. Without <code>--root</code>, existing defaults remain <code>memory/</code>, <code>changes/</code>, <code>domains/</code>, and <code>archive/</code>. If the default <code>memory/</code> already contains files, init preserves them and warns; use <code>--root .sdd</code> to avoid adding SDD memory documents alongside application documents.</p><h3 id="optional-external-mcp-sources" tabindex="-1">Optional: external MCP sources <a class="header-anchor" href="#optional-external-mcp-sources" aria-label="Permalink to &quot;Optional: external MCP sources&quot;">​</a></h3><p><code>sdd init</code> creates an empty <strong><code>.sdd/mcp.yaml</code></strong>. Register design-system / org / AST servers with <code>sdd mcp sources add …</code> so sdd can pull context at the right stage. See <a href="./../guides/mcp">MCP sources</a>.</p><p>After a <strong>new product</strong> path finishes, you may also see:</p><ul><li><code>memory/product.md</code></li><li><code>memory/requirements.md</code></li><li><code>memory/features.md</code></li><li><code>memory/architecture.md</code></li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./../concepts/change-packs">Change packs &amp; memory</a></li><li><a href="./../guides/agents">Set up your AI</a></li><li><a href="./../guides/mcp">MCP sources</a></li></ul>`,16)])])}const g=a(n,[["render",d]]);export{m as __pageData,g as default};
